#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT11

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  float humedad = dht.readHumidity();
  float temp = dht.readTemperature();
  Serial.print("Humedad: "); Serial.print(humedad);
  Serial.print("% | Temp: "); Serial.print(temp); Serial.println("°C");
  delay(2000);
}

