#include <SoftwareSerial.h>

SoftwareSerial miBT(10, 11);
const int pinRelay = 13;

void setup() {
  pinMode(pinRelay, OUTPUT);
  miBT.begin(9600);
}

void loop() {
  if (miBT.available()) {
    char dato = miBT.read();
    if (dato == 'A') {
      digitalWrite(pinRelay, HIGH);
    } else if (dato == 'B') {
      digitalWrite(pinRelay, LOW);
    }
  }
}

